const nowSec = Math.floor(Date.now() / 1000);
const state = $getWorkflowStaticData('global');
const out = [];
for (const item of $input.all()) {
  const c = item.json;
  const key = 'fb_' + c.id;
  const since = state[key] || (nowSec - 600);
  const filtering = encodeURIComponent(JSON.stringify([{ field: 'time_created', operator: 'GREATER_THAN', value: since }]));
  const url = 'https://graph.facebook.com/v21.0/' + encodeURIComponent(c.formId) + '/leads?access_token=' + encodeURIComponent(c.accessToken) + '&fields=id,created_time,ad_name,campaign_name,field_data&filtering=' + filtering + '&limit=100';
  out.push({ json: { connId: c.id, imobiliariaId: c.imobiliariaId, formId: c.formId, since: since, graphUrl: url } });
}
return out;

const state = $getWorkflowStaticData('global');
const prep = $('Preparar chamadas Graph').all();
const reslist = $input.all();
const out = [];
for (let i = 0; i < reslist.length; i++) {
  const meta = (prep[i] && prep[i].json) || {};
  const resp = reslist[i].json || {};
  const body = resp.body || resp;
  const status = resp.statusCode || 200;
  if (status >= 400 || (body && body.error)) {
    const msg = (body && body.error && body.error.message) || ('Graph API status ' + status);
    out.push({ json: { tipo: 'status', connId: meta.connId, ok: false, erro: String(msg).slice(0, 400), leadsCaptados: 0 } });
    continue;
  }
  const leads = Array.isArray(body.data) ? body.data : [];
  let maxTs = state['fb_' + meta.connId] || 0;
  const seenKey = 'fb_seen_' + meta.connId;
  const seen = new Set(state[seenKey] || []);
  let novos = 0;
  for (const L of leads) {
    const ts = Math.floor(new Date(L.created_time).getTime() / 1000);
    if (ts > maxTs) maxTs = ts;
    if (seen.has(L.id)) continue;
    seen.add(L.id);
    const fd = {};
    for (const f of (L.field_data || [])) { fd[String(f.name || '').toLowerCase()] = (f.values && f.values[0]) || ''; }
    const nome = fd.full_name || fd.nome || fd.name || fd.nome_completo || 'Lead do Facebook';
    const telefone = fd.phone_number || fd.telefone || fd.phone || fd.whatsapp || fd.celular || '';
    const email = fd.email || fd['e-mail'] || '';
    if (!telefone) continue;
    const campanha = L.campaign_name || L.ad_name || '';
    novos++;
    out.push({ json: { tipo: 'lead', imobiliariaId: meta.imobiliariaId, connId: meta.connId, nome: nome, telefone: telefone, email: email, mensagem: fd.mensagem || fd.message || '', campanha: campanha } });
  }
  state['fb_' + meta.connId] = maxTs;
  state[seenKey] = Array.from(seen).slice(-300);
  out.push({ json: { tipo: 'status', connId: meta.connId, ok: true, erro: '', leadsCaptados: novos } });
}
return out;
